record Bag(int sizeGrams, int leftGrams, LocalDate bestBefore) {}

final class Shopping {
    // core: static, every input is a parameter, the result is the only output
    static int gramsToBuy(int neededGrams, Bag bag, LocalDate today) {
        int usable = today.isAfter(bag.bestBefore()) ? 0 : bag.leftGrams();
        int missing = Math.max(neededGrams - usable, 0);
        int bags = (missing + bag.sizeGrams() - 1) / bag.sizeGrams();
        return bags * bag.sizeGrams();
    }

    static String shoppingLine(String ingredient, int grams, LocalDate today) {
        return today + ": buy " + grams + " g " + ingredient;
    }

    // shell: gather, decide, act
    static int flourToBuy(int neededGrams, Clock clock, List<String> list) {
        Bag bag = Cupboard.flour;
        LocalDate today = LocalDate.now(clock);
        int grams = gramsToBuy(neededGrams, bag, today);
        list.add(shoppingLine("flour", grams, today));
        return grams;
    }
}

kotlin.src:
data class Bag(val sizeGrams: Int, val leftGrams: Int, val bestBefore: LocalDate)

// core: a top-level function, every input is a parameter, the result is the only output
fun gramsToBuy(neededGrams: Int, bag: Bag, today: LocalDate): Int {
    val usable = if (today.isAfter(bag.bestBefore)) 0 else bag.leftGrams
    val missing = maxOf(neededGrams - usable, 0)
    val bags = (missing + bag.sizeGrams - 1) / bag.sizeGrams
    return bags * bag.sizeGrams
}

fun shoppingLine(ingredient: String, grams: Int, today: LocalDate) = "$today: buy $grams g $ingredient"

// shell: gather, decide, act
fun flourToBuy(neededGrams: Int, clock: Clock, list: MutableList<String>): Int {
    val bag = Cupboard.flour
    val today = LocalDate.now(clock)
    val grams = gramsToBuy(neededGrams, bag, today)
    list.add(shoppingLine("flour", grams, today))
    return grams
}

