fun decide(recipe: Recipe, now: LocalTime, inCupboard: Set<String>): Plan = when {
    now.plusMinutes(recipe.minutes.toLong()).isAfter(DINNER_TIME) ->
        Plan.Skip(recipe.name, "not enough time")
    !inCupboard.containsAll(recipe.ingredients) ->
        Plan.Skip(recipe.name, "something is missing")
    else -> Plan.Cook(recipe.name, recipe.minutes, recipe.ingredients)
}

