static Plan decide(Recipe recipe, LocalTime now, Set<String> inCupboard) {
    if (now.plusMinutes(recipe.minutes()).isAfter(DINNER_TIME))
        return new Plan.Skip(recipe.name(), "not enough time");
    if (!inCupboard.containsAll(recipe.ingredients()))
        return new Plan.Skip(recipe.name(), "something is missing");
    return new Plan.Cook(recipe.name(), recipe.minutes(), recipe.ingredients());
}

