fun cookTonight(recipeName: String) {
    val recipe = book.load(recipeName)                                         // 1. gather
    when (val plan = decide(recipe, LocalTime.now(clock), cupboard.contents())) {  // 2. decide
        is Plan.Cook -> {                                                       // 3. act
            timer.start(plan.minutes)
            cupboard.use(plan.ingredients)
        }
        is Plan.Skip -> log.warn("${plan.recipe}: ${plan.reason}")
    }
}

