void cookTonight(String recipeName) {
    Recipe recipe = book.load(recipeName);                                         // 1. gather
    switch (decide(recipe, LocalTime.now(clock), cupboard.contents())) {           // 2. decide
        case Plan.Cook c -> {                                                      // 3. act
            timer.start(c.minutes());
            cupboard.use(c.ingredients());
        }
        case Plan.Skip s -> log.warn(s.recipe() + ": " + s.reason());
    }
}

